using System;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace IntConditionalInc;

public class ConditionalIncrement
{
    public static void IncrementAbove(Span<int> data, int threshold)
    {
        if (Vector512.IsHardwareAccelerated && data.Length >= Vector512<int>.Count)
        {
            IncrementAboveVector512(data, threshold);
        }
        else if (Vector256.IsHardwareAccelerated && data.Length >= Vector256<int>.Count)
        {
            IncrementAboveVector256(data, threshold);
        }
        else if (Vector128.IsHardwareAccelerated && data.Length >= Vector128<int>.Count)
        {
            IncrementAboveVector128(data, threshold);
        }
        else
        {
            IncrementAboveScalar(data, threshold);
        }
    }

    private static void IncrementAboveVector512(Span<int> data, int threshold)
    {
        var thresholdVec = Vector512.Create(threshold);
        var oneVec = Vector512.Create(1);
        var vectors = MemoryMarshal.Cast<int, Vector512<int>>(data);

        for (int i = 0; i < vectors.Length; i++)
        {
            var mask = Vector512.GreaterThan(vectors[i], thresholdVec);
            vectors[i] += mask & oneVec;
        }

        // Handle remaining elements
        int processed = vectors.Length * Vector512<int>.Count;
        IncrementAboveScalar(data.Slice(processed), threshold);
    }

    private static void IncrementAboveVector256(Span<int> data, int threshold)
    {
        var thresholdVec = Vector256.Create(threshold);
        var oneVec = Vector256.Create(1);
        var vectors = MemoryMarshal.Cast<int, Vector256<int>>(data);

        for (int i = 0; i < vectors.Length; i++)
        {
            var mask = Vector256.GreaterThan(vectors[i], thresholdVec);
            vectors[i] += mask & oneVec;
        }

        int processed = vectors.Length * Vector256<int>.Count;
        IncrementAboveScalar(data.Slice(processed), threshold);
    }

    private static void IncrementAboveVector128(Span<int> data, int threshold)
    {
        var thresholdVec = Vector128.Create(threshold);
        var oneVec = Vector128.Create(1);
        var vectors = MemoryMarshal.Cast<int, Vector128<int>>(data);

        for (int i = 0; i < vectors.Length; i++)
        {
            var mask = Vector128.GreaterThan(vectors[i], thresholdVec);
            vectors[i] += mask & oneVec;
        }

        int processed = vectors.Length * Vector128<int>.Count;
        IncrementAboveScalar(data.Slice(processed), threshold);
    }

    private static void IncrementAboveScalar(Span<int> data, int threshold)
    {
        for (int i = 0; i < data.Length; i++)
        {
            if (data[i] > threshold)
                data[i]++;
        }
    }
}

